    Normalize declaration arguments

    Args:
        sequence (list): List of Declarions, tuples, or single interfaces
        output (list): List to store the normalized arguments

    Returns:
        list: Normalized arguments
    """
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, tuple):
            output.extend(item)
        elif isinstance(item, Declarion):
            output.append(item)
        elif isinstance(item, Interface):
            output.extend(item.spec)
