def difference(d1, d2, level=-1):
    result = {}
    if level == 0:
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
        return result
    elif level == -1:
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
            elif type(d1[key]) is dict:
                from copy import deepcopy
                d2_key = deepcopy(d2[key])
                result_key = difference(d1[key], d2_key, level)
                if result_key:
                    result[key] = result_key
        return result
    else:
        raise ValueError("Invalid value for 'level' parameter. The valid range is [-1, inf].")

