        filepaths = zipped.namelist()
        xml_basenames = []
        for filename in filepaths:
            xml_basenames.append(os.path.basename(filename))
        xml_data = {basename: {
            'notes': [],
            'degrades_when_kept': []
        } for basename in xml_basenames}
        for filename in filepaths:
            basename = os.path.basename(filename)
            with zipped.open(filename, 'r') as f:
                text = f.read()
                soup = BeautifulSoup(text, 'xml')
                notes = []
                degrades_when_kept = []
                for p in soup.findAll('degrades_when_kept'):
                    if p.text not in degrades_when_kept:
                        degrades_when_kept.append(p.text)
                for n in soup.findAll('note'):
                    if n.text not in notes:
                        notes.append(n.text)
                xml_data[basename]['notes'].extend(notes)
                xml_data[basename]['degrades_when_kept'].extend(degrades_when_kept)
        return xml_data

