def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    # Validate input
    if not url:
        raise ValueError("url is required")

    # Build URL
    base_url = urlparse(url)
    if not document_path:
        document_path = f"{base_url.netloc}/.well-known/nodeinfo"
    else:
        document_path = f"{base_url.netloc}/{document_path}"

    # Make GET request
    try:
        response = get(document_path)
    except Exception as e:
        raise ConnectionError(f"Could not retrieve document from {document_path}: {e}")

    # Check status code
    if response.status_code != 200:
        raise ConnectionError(f"Received status code {response.status_code} from {document_path}")

    # Parse JSON
    try:
        return json.loads(response.text)
    except JSONDecodeError as e:
        raise ParseError(f"Could not parse JSON response: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    if not document:
        raise ValueError("Invalid input: document cannot be empty string")

    document = document.strip()
    if not document:
        raise ValueError("Invalid input: document cannot be only whitespace")

    try:
        payload = json.loads(document)
    except json.JSONDecodeError:
        try:
            # try parsing document as XRD
            parser = XRDParser()
            parser.feed(document)
            payload = parser.payload
        except Exception:
            # could not parse document as XRD or JSON
            raise ValueError("Invalid input: document is not in JSON or XRD format")

    if not payload:
        raise ValueError("Invalid input: document is empty or invalid")

    if not isinstance(payload, dict):
        raise ValueError("Invalid input: document is not a JSON object")

    # check if payload has required fields
    for field in ["subject", "aliases", "services"]:
        if field not in payload:
            raise ValueError(f"Invalid input: document does not contain required field '{field}'")

    return payload

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
