def validate_from_content(cls, spec_content=None):
    """validates that spec content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is not provided.")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid YAML syntax in spec content.") from e

    missing = []
    for field in cls.required_fields:
        if field not in spec:
            missing.append(field)

    if missing:
        raise IRValidatorException(f"Required field(s) missing: {', '.join(missing)}")

    return spec

def validate_from_file(cls, yaml_file: str = None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    data = {}
    if yaml_file is not None:
        with open(yaml_file, "r") as f:
            data = yaml.load(f, Loader=yaml.FullLoader)

    mandatory_keys = ["name", "description", "test_cases"]
    for key in mandatory_keys:
        if key not in data:
            raise IRValidatorException(f"Mandatory data '{key}' is missing in YAML file")

    return data

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    Args:
        parser_dict: The parser dictionary.

    Returns:
        The updated parser dictionary with the included groups.
    """
    included_groups = {}
    for group, members in parser_dict.items():
        if group == "include":
            included_groups.update(members)
            parser_dict.pop(group)
        elif group in included_groups:
            members.update(included_groups[group])
    return parser_dict

def get_spec_defaults(self) -> typing.Dict[str, typing.Any]:
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    for argument_name, argument_spec in self.spec.items():
        if "default" in argument_spec:
            spec_defaults[argument_name] = argument_spec["default"]
        elif "fallback" in argument_spec:
            spec_defaults[argument_name] = argument_spec["fallback"]
        else:
            spec_defaults[argument_name] = None
    return spec_defaults

def get_deprecated_args(self):
    """
    Returning dict with options which deprecate others.
    """
    deprecated_args = {}
    for arg in self.kwargs:
        if arg in self.deprecated_args:
            deprecated_args[arg] = self.kwargs[arg]
            for deprecated_arg in self.deprecated_args[arg]:
                if deprecated_arg in self.kwargs:
                    del self.kwargs[deprecated_arg]
    return deprecated_args

