def get_parser_option_specs(self, command_name):
    if not command_name:
        raise ValueError("Missing command name argument")
    elif command_name not in self.command_map:
        raise ValueError(f"Invalid command name provided: {command_name}")
    return self.command_map[command_name].option_specs

def get_option_spec(self, command_name, argument_name):
    try:
        option_specs = self.get_option_specs(command_name)
        for option_spec in option_specs:
            if option_spec.name == argument_name:
                return option_spec
        raise ValueError("Option with specified name not found.")
    except Exception as e:
        print(f"Error: {e}")
