def _get_conditionally_required_args(self, command_name, options_spec, args):
    conditionally_required_args = []
    for option in options_spec:
        if option.get('required_when'):
            for when_condition in option.get('required_when'):
                if when_condition.get(command_name) and self._get_arg(when_condition.get('when_parameter'), args):
                    conditionally_required_args.append(option.get('name'))
    return conditionally_required_args

