def validate_min_max_args(self, args):
    # Check if there are more than 2 arguments
    if len(args) > 2:
        raise ValueError("Too many arguments passed")
    # Check if there are less than 2 arguments
    if len(args) < 2:
        raise ValueError("Not enough arguments passed")
    # Check if the first argument is less than the second argument
    if args[0] > args[1]:
        raise ValueError("The first argument should be less than the second argument")
    # Return true if all conditions are met
    return True

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith("--") or arg.startswith("-"):
            control_args[arg.lstrip("-").lstrip("-")] = args[arg]
        elif arg.startswith("--/") or arg.startswith("-/"):
            nested_args[arg.lstrip("/").lstrip("-")] = args[arg]
    return control_args, nested_args

