def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Initialize ansible-playbook command
    ansible_playbook_cmd = ["ansible-playbook"]
    # Add workspace option if provided
    if ir_workspace:
        ansible_playbook_cmd += ["-ir-workspace", ir_workspace]
    # Add plugin option if provided
    if ir_plugin:
        ansible_playbook_cmd += ["-ir-plugin", ir_plugin]
    # Add playbook path option if provided
    if playbook_path:
        ansible_playbook_cmd += [playbook_path]
    # Add verbosity option if provided
    if verbose:
        ansible_playbook_cmd += ["-v"]
        ansible_playbook_cmd += [verbose]
    # Add extra vars option if provided
    if extra_vars:
        # Add '--extra-vars' option
        ansible_playbook_cmd += ["-e"]
        # Add all extra vars key-value pairs
        for key, value in extra_vars.items():
            ansible_playbook_cmd += ["--extra-vars", f"{key}={value}"]
    # Add ansible args option if provided
    if ansible_args:
        for key, value in ansible_args.items():
            # Only add option if not None
            if value is not None:
                ansible_playbook_cmd += ["-{}".format(key), str(value)]
    # Execute 'ansible-playbook' command
    result = subprocess.run(ansible_playbook_cmd, stdout=subprocess.PIPE)
    # Return result
    return result.stdout.decode()

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == 'main':
        if 'mem' in values_dict:
            values_dict['mem'] = int(values_dict['mem'])
        if 'cpu' in values_dict:
            values_dict['cpu'] = int(values_dict['cpu'])
        if 'user' in values_dict:
            values_dict['user'] = int(values_dict['user'])
    elif parser_name == 'virsh':
        if 'freebox' in values_dict:
            values_dict['freebox'] = int(values_dict['freebox'])
        if 'oc mundo' in values_dict:
            values_dict['oc mundo'] = int(values_dict['oc mundo'])
    elif parser_name == 'ospd':
        if 'berechi' in values_dict:
            values_dict['berechi'] = int(values_dict['berechi'])
    else:
        raise ValueError(f"Unsupported parser name: {parser_name}")

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    try:
        with open(os.path.join(plugin_dir, "plugin.json"), "r") as f:
            plugin_spec = json.load(f)
    except FileNotFoundError as e:
        raise ValueError(f"plugin.json not found in {plugin_dir}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON data in plugin.json") from e

    flat_spec = {}
    for k, v in plugin_spec.items():
        if isinstance(v, dict):
            for sub_k, sub_v in v.items():
                flat_spec[f"{k}.{sub_k}"] = sub_v
        else:
            flat_spec[k] = v

    return flat_spec

